<template>
  <section class="insights" aria-label="운영 분석">
    <p v-if="loading" role="status" class="insights-loading">분석 정보를 불러오는 중입니다...</p>
    <div v-else class="insights-grid">
      <article v-if="section === 'sentiment'" class="insight-card insight-wide"><div class="insight-card-head"><div><span class="insight-eyebrow">리뷰 분석</span><h3>리뷰 감성 분포</h3></div><div class="sentiment-actions"><button type="button" class="insight-link" :disabled="analyzing" @click="runAnalysis">{{ analyzing ? '리뷰 분석 중…' : '리뷰 감성분석 실행' }}</button><button type="button" class="insight-link" @click="$emit('show-reviews')">리뷰 관리 →</button></div></div>
        <p v-if="errors.sentiment" class="insight-error" role="alert">{{ errors.sentiment }}</p>
        <template v-else-if="sentiment"><div class="coverage">전체 리뷰 <b>{{ number(sentiment.total_reviews) }}건</b><span>·</span> 분석된 리뷰 <b>{{ number(sentiment.analyzed_reviews) }}건</b></div>
          <template v-if="sentiment.analyzed_reviews"><AnalysisDonut title="감성 분석 비중" :items="sentimentChart" unit="건" center-label="분석된 리뷰" /><div class="sentiment-legend"><div v-for="part in sentiments" :key="part.key"><i :class="part.key.toLowerCase()"></i><span>{{ part.label }}</span><strong>{{ number(sentiment.counts[part.key]) }}건 <small>({{ percent(sentiment.counts[part.key], sentiment.analyzed_reviews) }}%)</small></strong></div></div><p class="insight-footnote">마지막 분석 {{ dateTime(sentiment.last_analyzed_at) }} · 분석 방식: {{ sentiment.model_versions.map(v=>v.includes('hf-bert')?'BERT':v.includes('lexicon')?'한국어 감성 사전':'머신러닝').join(', ') }}</p></template>
          <div v-else class="insight-empty"><strong>아직 저장된 감성분석 결과가 없습니다.</strong></div></template>
        <section v-if="sentiment?.analyzed_reviews" class="sentiment-results"><h4>리뷰별 분석 결과</h4><select v-model="reviewLabel" aria-label="감성 결과 필터" @change="loadResults(1)"><option value="">전체 감성</option><option v-for="part in sentiments" :key="part.key" :value="part.key">{{ part.label }}</option></select><p v-if="resultError" role="alert">{{ resultError }}</p><article v-for="review in results" :key="review.review_id"><span class="sentiment-tag" :class="review.label.toLowerCase()">{{ sentiments.find(p=>p.key===review.label)?.label }}</span><b>{{ review.book_title }}</b><p>{{ review.content }}</p></article><p v-if="!results.length">해당 감성의 리뷰가 없습니다.</p><div v-if="resultPages>1"><button :disabled="resultPage<=1" @click="loadResults(resultPage-1)">이전</button> {{ resultPage }} / {{ resultPages }} <button :disabled="resultPage>=resultPages" @click="loadResults(resultPage+1)">다음</button></div></section>
      </article>
      <article v-if="section === 'sales'" class="insight-card insight-wide"><div class="insight-card-head"><div><span class="insight-eyebrow">판매 현황</span><h3>인기 도서 분야</h3><p>최근 30일 · 결제 완료 후 진행된 주문 기준</p></div></div><p v-if="errors.sales" class="insight-error" role="alert">{{ errors.sales }}</p><template v-else><AnalysisDonut v-if="categories.length" title="분야별 판매 수량 비중" :items="categoryChart" unit="권" center-label="상위 5개 분야 판매" /><div v-if="categories.length" class="category-list"><div v-for="(category,index) in categories" :key="category.category_id"><span class="rank">{{ index+1 }}</span><div class="category-name"><strong>{{ category.category_name }}</strong><small>{{ number(category.quantity) }}권 · {{ number(category.order_count) }}건</small></div><b>{{ money(category.net_amount) }}</b></div></div><div v-else class="insight-empty"><strong>해당 기간의 판매 내역이 없습니다.</strong></div><p v-if="categories.length" class="insight-footnote">상품 금액 기준 · 쿠폰·배송비·취소액 미반영</p></template></article>
      <article v-if="section === 'customers'" class="insight-card insight-wide"><div class="insight-card-head"><div><span class="insight-eyebrow">고객 분석</span><h3>고객 구매 현황</h3><p>결제 완료 후 진행된 회원 주문 기준</p></div></div><p v-if="errors.customers" class="insight-error" role="alert">{{ errors.customers }}</p><template v-else-if="customers"><div class="customer-metrics"><div><span>재구매율</span><strong>{{ customers.repurchase_rate.toFixed(1) }}<small>%</small></strong><p>구매 회원 중 2회 이상 구매한 비율</p></div><div><span>최근 30일 신규 회원</span><strong>{{ number(customers.new_members_30d) }}<small>명</small></strong><p>탈퇴하지 않은 회원 기준</p></div></div><AnalysisDonut title="재구매 회원 비중" :items="repurchaseChart" unit="%" :center-value="`${Number(customers.repurchase_rate || 0).toFixed(1)}%`" center-label="재구매율" /><AnalysisDonut v-if="customers.segments.length" title="고객 유형별 분포" :items="segmentChart" unit="명" center-label="유형 분석 회원" /><div class="insight-subheading">고객 유형 분석</div><div v-if="customers.segments.length" class="segment-list"><div v-for="segment in customers.segments" :key="segment.rfm_segment"><span>{{ segmentLabel(segment.rfm_segment) }}</span><b>{{ number(segment.member_count) }}명</b></div></div><p v-else class="insight-footnote">저장된 고객 유형 분석 결과가 없습니다.</p></template></article>
      <article v-if="section === 'churn'" class="insight-card insight-wide"><div class="insight-card-head"><div><span class="insight-eyebrow">고객 분석</span><h3>이탈 가능성 분석</h3></div><div class="sentiment-actions"><button type="button" class="insight-link" :disabled="churnRunning" @click="runChurn">{{ churnRunning ? '이탈 예측 중…' : '이탈 예측 실행' }}</button></div></div><p v-if="errors.churn" class="insight-error" role="alert">{{ errors.churn }}</p><template v-else-if="churn"><AnalysisDonut v-if="churn.total_scored" title="이탈 위험도 분포" :items="churnChart" unit="명" center-label="분석 대상" /><div v-if="churn.total_scored" class="risk-grid"><div><span>높음</span><strong>{{ number(churn.high_risk_count) }}<small>명</small></strong></div><div><span>보통</span><strong>{{ number(churn.mid_risk_count) }}<small>명</small></strong></div><div><span>낮음</span><strong>{{ number(churn.low_risk_count) }}<small>명</small></strong></div><div><span>분석 대상</span><strong>{{ number(churn.total_scored) }}<small>명</small></strong></div></div><div v-else class="insight-empty"><strong>저장된 이탈 예측 결과가 없습니다.</strong><p>오른쪽 위 '이탈 예측 실행'을 누르면 회원 구매 기록으로 모델을 학습하고 결과를 저장합니다.</p></div><p v-if="churn.total_scored" class="insight-footnote">마지막 예측 {{ dateTime(churn.predicted_at) }}</p></template></article>
    </div>

  </section>
</template>
<script setup>
import { computed, ref, watch } from 'vue';
import http from '../../api/http';
import AnalysisDonut from '../AnalysisDonut.vue';
defineEmits(['show-reviews']);
const props=defineProps({section:{type:String,required:true}});
const loading=ref(true),sentiment=ref(null),categories=ref([]),customers=ref(null),churn=ref(null),errors=ref({});
const sentiments=[{key:'POSITIVE',label:'긍정'},{key:'NEUTRAL',label:'중립'},{key:'NEGATIVE',label:'부정'}];
const number=n=>Number(n||0).toLocaleString('ko-KR'),money=n=>`${number(n)}원`,percent=(n,total)=>total?Math.round(Number(n||0)*1000/total)/10:0;
const dateTime=value=>value?new Date(value).toLocaleString('ko-KR',{timeZone:'Asia/Seoul'}):'확인되지 않음';
const sentimentAria=computed(()=>sentiment.value ? sentiments.map(p=>`${p.label} ${number(sentiment.value.counts[p.key])}건`).join(', '):'');
const segmentLabel=value=>({VIP:'우수 고객',LOYAL:'충성 고객',NEW:'신규 고객',ACTIVE:'활동 고객',AT_RISK:'이탈 위험 고객',CANT_LOSE:'관리 필요 고객',GENERAL:'일반 고객',DORMANT:'휴면 고객',CHAMPIONS:'최우수 고객',POTENTIAL:'잠재 고객'}[value] || '기타 고객');
const sentimentChart=computed(()=>sentiments.map(part=>({label:part.label,value:sentiment.value?.counts?.[part.key]||0})));
const categoryChart=computed(()=>categories.value.map(category=>({label:category.category_name,value:category.quantity})));
const segmentChart=computed(()=>(customers.value?.segments||[]).map(segment=>({label:segmentLabel(segment.rfm_segment),value:segment.member_count})));
const repurchaseChart=computed(()=>{const rate=Math.min(100,Math.max(0,Number(customers.value?.repurchase_rate)||0));return [{label:'2회 이상 구매',value:rate},{label:'1회 구매',value:100-rate,color:'#ded4eb'}];});
const churnChart=computed(()=>[{label:'높음',value:churn.value?.high_risk_count,color:'#d58e9d'},{label:'보통',value:churn.value?.mid_risk_count,color:'#d4ae69'},{label:'낮음',value:churn.value?.low_risk_count,color:'#68a9a1'}]);
const analyzing=ref(false),results=ref([]),reviewLabel=ref(''),resultPage=ref(1),resultPages=ref(1),resultError=ref('');
let resultGeneration=0;
async function loadResults(page=1){const token=++resultGeneration;try{resultError.value='';const {data}=await http.get('/api/v1/admin/analysis/review-sentiment/reviews',{params:{page,label:reviewLabel.value||undefined}});if(token!==resultGeneration)return;results.value=data.items;resultPage.value=data.meta.page;resultPages.value=data.meta.total_pages||1}catch(e){if(token===resultGeneration)resultError.value=e.userMessage||'리뷰를 불러오지 못했습니다.'}}
async function runAnalysis(){if(analyzing.value)return;analyzing.value=true;try{await http.post('/api/v1/admin/analysis/review-sentiment/run',null,{timeout:600000});if(props.section==='sentiment')await load()}catch(e){errors.value={sentiment:e.userMessage||'분석 실행에 실패했습니다.'}}finally{analyzing.value=false}}
const churnRunning=ref(false);
async function runChurn(){if(churnRunning.value)return;churnRunning.value=true;try{await http.post('/api/v1/ai/train/churn',null,{params:{async_mode:false},timeout:600000});if(props.section==='churn')await load()}catch(e){errors.value={churn:e.userMessage||'이탈 예측 실행에 실패했습니다.'}}finally{churnRunning.value=false}}
let generation=0;
const requests={sentiment:()=>http.get('/api/v1/admin/analysis/review-sentiment'),sales:()=>http.get('/api/v1/ai/sales/categories',{params:{limit:5}}),customers:()=>http.get('/api/v1/ai/customers/analysis'),churn:()=>http.get('/api/v1/ai/customers/churn',{params:{limit:1}})};
const targets={sentiment,categories,customers,churn};
async function load(){const token=++generation,section=props.section;loading.value=true;errors.value={};try{const response=await requests[section]();if(token!==generation)return;(section==='sales'?targets.categories:targets[section]).value=response.data;if(section==='sentiment')await loadResults(1)}catch{if(token===generation)errors.value[section]='데이터를 불러오지 못했습니다. 잠시 후 다시 시도해 주세요.'}finally{if(token===generation)loading.value=false}}
watch(()=>props.section,load,{immediate:true});
defineExpose({ refresh: load, loading, analyzing, churnRunning });
</script>
<style scoped>
