gory-name{display:flex;flex:1;min-width:0;flex-direction:column;gap:4px;font-size:13px}.category-name small{color:#988f9a}.category-list b{font-size:13px;white-space:nowrap}.customer-metrics{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:20px}.customer-metrics>div,.risk-grid>div{padding:16px;border-radius:8px;background:#f8f6fa}.customer-metrics span,.risk-grid span{display:block;color:#827888;font-size:12px}.customer-metrics strong,.risk-grid strong{display:block;margin-top:9px;color:#684494;font-size:23px}.customer-metrics strong small,.risk-grid strong small{margin-left:3px;font-size:12px}.customer-metrics p{margin:7px 0 0;color:#998f9d;font-size:11px;line-height:1.4}.insight-subheading{margin-top:22px;font-size:13px;font-weight:700}.segment-list>div{display:flex;justify-content:space-between;padding:10px 0;border-bottom:1px solid #f2eef3;font-size:13px}.risk-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-top:20px}.insight-error{color:#a32c2c;font-size:13px}.insights-loading{color:#817788}@media(max-width:700px){.insights-grid{grid-template-columns:1fr}.insight-wide{grid-column:auto}.insight-card{padding:19px}.sentiment-legend{grid-template-columns:1fr}.risk-grid{grid-template-columns:repeat(2,1fr)}.insight-card-head{flex-wrap:wrap}}
.insights{font-size:16px}.insights-head p,.insight-card-head p,.insights-head button,.insight-link,.coverage,.sentiment-legend>div,.category-name,.category-list b,.segment-list>div,.insight-empty,.insight-error{font-size:16px}.insight-eyebrow,.customer-metrics span,.risk-grid span,.insight-footnote,.insights-note,.customer-metrics p,.insight-subheading{font-size:15px}.insight-card h3{font-size:21px}.customer-metrics strong,.risk-grid strong{font-size:27px}.customer-metrics strong small,.risk-grid strong small{font-size:15px}.category-name small,.sentiment-legend small{font-size:14px}.insight-card-head p,.insight-footnote,.insights-note,.customer-metrics p{line-height:1.6}
</style>

<style scoped>
.sentiment-actions{display:flex;flex-wrap:wrap;gap:8px}.sentiment-actions button:disabled{opacity:.5;cursor:wait}.sentiment-results{margin-top:28px;border-top:1px solid #e9e1ef;padding-top:20px}.sentiment-results select{padding:10px;border:1px solid #ded2e9;border-radius:8px;font:inherit}.sentiment-results article{padding:18px 0;border-bottom:1px solid #eee7f3}.sentiment-tag{display:inline-block;padding:4px 10px;border-radius:6px;color:white;font-size:13px;margin-right:10px}.sentiment-results article p{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.7;color:#75657f}.sentiment-results button{padding:8px 14px;border-radius:8px;color:#6841a4;margin-top:16px}
